import Foundation

enum PostcardCareCategory: String, CaseIterable, Equatable, Hashable {
    case nightCare
    case movementBreak
    case hydrationFood
    case sleepShutdown
    case workRhythm
    case hurtMisunderstood
    case informationOverload
    case lowBattery
    case selfBlameFailure
    case missingHome
    case gentleEncouragement
    case smallTips
    case weatherSeason
    case morningRestart
}

struct PostcardCareCategorySelection: Equatable {
    let preferred: [PostcardCareCategory]
    let fallback: [PostcardCareCategory]
}

enum PostcardCareTimeRules {
    static let minimumSpacing: TimeInterval = 60 * 90

    static func selection(for date: Date, calendar: Calendar = .current) -> PostcardCareCategorySelection {
        let minute = minuteOfDay(for: date, calendar: calendar)
        switch minute {
        case 360..<630:
            return PostcardCareCategorySelection(
                preferred: [.morningRestart, .gentleEncouragement, .weatherSeason],
                fallback: [.missingHome, .smallTips]
            )
        case 630..<810:
            return PostcardCareCategorySelection(
                preferred: [.hydrationFood, .workRhythm, .smallTips],
                fallback: [.missingHome, .weatherSeason]
            )
        case 810..<1050:
            return PostcardCareCategorySelection(
                preferred: [.movementBreak, .workRhythm, .informationOverload, .lowBattery],
                fallback: [.hydrationFood, .gentleEncouragement, .smallTips]
            )
        case 1050..<1170:
            return PostcardCareCategorySelection(
                preferred: [.sleepShutdown, .hydrationFood, .hurtMisunderstood],
                fallback: [.missingHome, .weatherSeason]
            )
        case 1170..<1290:
            return PostcardCareCategorySelection(
                preferred: [.nightCare, .hurtMisunderstood, .informationOverload, .selfBlameFailure],
                fallback: [.hydrationFood, .missingHome]
            )
        case 1290..<1410:
            return PostcardCareCategorySelection(
                preferred: [.nightCare, .sleepShutdown, .lowBattery, .selfBlameFailure],
                fallback: [.missingHome]
            )
        case 1410..<1440, 0..<360:
            return PostcardCareCategorySelection(
                preferred: [.nightCare, .sleepShutdown],
                fallback: [.lowBattery]
            )
        default:
            return PostcardCareCategorySelection(
                preferred: [.missingHome, .weatherSeason],
                fallback: [.hurtMisunderstood, .selfBlameFailure]
            )
        }
    }

    static func normalizedDeliveryDate(for date: Date, calendar: Calendar = .current) -> Date {
        let minute = minuteOfDay(for: date, calendar: calendar)
        guard minute >= 1410 || minute < 360 else {
            return date
        }

        var components = calendar.dateComponents([.year, .month, .day], from: date)
        components.hour = 6
        components.minute = 30
        components.second = 0
        components.nanosecond = 0
        let baseDay = calendar.date(from: components) ?? date
        if minute >= 1410 {
            return calendar.date(byAdding: .day, value: 1, to: baseDay) ?? date.addingTimeInterval(60 * 60 * 7)
        }
        return baseDay
    }

    static func minuteOfDay(for date: Date, calendar: Calendar = .current) -> Int {
        let components = calendar.dateComponents([.hour, .minute], from: date)
        return (components.hour ?? 0) * 60 + (components.minute ?? 0)
    }
}

struct PostcardNarrative: Equatable {
    let id: String
    let animalKey: String
    let careCategory: PostcardCareCategory
    let body: String
}

enum PostcardTextLibrary {
    static let fallbackAnimalKey = "xiaoman_hamster"

    static func randomEntry(
        for animal: Animal,
        on date: Date,
        calendar: Calendar = .current,
        excluding consumedIds: Set<String>
    ) -> PostcardNarrative? {
        randomEntry(
            forResolvedAnimalKey: animalKey(for: animal),
            on: date,
            calendar: calendar,
            excluding: consumedIds,
            allowConsumedFallback: false
        )
    }

    static func randomEntry(
        forAnimalKey animalKey: String,
        on date: Date,
        calendar: Calendar = .current,
        excluding consumedIds: Set<String>,
        allowConsumedFallback: Bool = false
    ) -> PostcardNarrative? {
        let resolvedAnimalKey = hasEntries(forAnimalKey: animalKey) ? animalKey : fallbackAnimalKey
        return randomEntry(
            forResolvedAnimalKey: resolvedAnimalKey,
            on: date,
            calendar: calendar,
            excluding: consumedIds,
            allowConsumedFallback: allowConsumedFallback
        )
    }

    static func containsCareBody(_ body: String) -> Bool {
        careBodies.contains(body)
    }

    static func animalKey(forAssetName assetName: String) -> String? {
        canonicalAnimalKey(in: assetName)
    }

    private static func randomEntry(
        forResolvedAnimalKey animalKey: String,
        on date: Date,
        calendar: Calendar,
        excluding consumedIds: Set<String>,
        allowConsumedFallback: Bool
    ) -> PostcardNarrative? {
        let selection = PostcardCareTimeRules.selection(for: date, calendar: calendar)
        let entries = narratives.filter { $0.animalKey == animalKey }
        let available = entries.filter { consumedIds.contains($0.id) == false }
        if let entry = randomEntry(in: available, categories: selection.preferred) ??
            randomEntry(in: available, categories: selection.fallback)
        {
            return entry
        }

        guard allowConsumedFallback else { return nil }
        return randomEntry(in: entries, categories: selection.preferred) ??
            randomEntry(in: entries, categories: selection.fallback) ??
            entries.randomElement()
    }

    static func randomEntry(for animal: Animal, excluding consumedIds: Set<String>) -> PostcardNarrative? {
        randomEntry(for: animal, on: Date(), excluding: consumedIds)
    }

    private static func randomEntry(
        in entries: [PostcardNarrative],
        categories: [PostcardCareCategory]
    ) -> PostcardNarrative? {
        guard categories.isEmpty == false else { return nil }
        let categorySet = Set(categories)
        return entries.filter { categorySet.contains($0.careCategory) }.randomElement()
    }

    static func animalKey(for animal: Animal) -> String {
        canonicalAnimalKey(in: animal.id) ??
            canonicalAnimalKey(in: animal.homeAssetName) ??
            animal.id
    }

    private static func hasEntries(forAnimalKey animalKey: String) -> Bool {
        narratives.contains { $0.animalKey == animalKey }
    }

    private static func canonicalAnimalKey(in value: String) -> String? {
        let normalizedValue = value.lowercased()
        if normalizedValue.contains("xiaoman_hamster") {
            return "xiaoman_hamster"
        }
        if normalizedValue.contains("tangyuan_puppy") {
            return "tangyuan_puppy"
        }
        if normalizedValue.contains("moji_cat") {
            return "moji_cat"
        }
        if normalizedValue.contains("dengdeng_rabbit") {
            return "dengdeng_rabbit"
        }
        if normalizedValue.contains("feifei_parrot") {
            return "feifei_parrot"
        }
        if normalizedValue.contains("xiaolu_guinea_pig") {
            return "xiaolu_guinea_pig"
        }
        if normalizedValue.contains("deer_visitor") || normalizedValue.contains("jiujiu_deer") {
            return "deer_visitor"
        }
        if normalizedValue.contains("fox_visitor") || normalizedValue.contains("aini_fox") {
            return "fox_visitor"
        }
        if normalizedValue.contains("bear_visitor") || normalizedValue.contains("dundun_bear") {
            return "bear_visitor"
        }
        return nil
    }

    // Generated by Tools/generate_postcard_text_library.py from Content/AnimalDatabase/PostcardGreetingCare_1.0_Draft.md.
    static let narratives: [PostcardNarrative] = [
        PostcardNarrative(id: "xiaoman_hamster_care10_01_001", animalKey: "xiaoman_hamster", careCategory: .nightCare, body: "刚刚有没有终于安静一点？手边放杯温水，慢慢坐着就好。小满希望这张明信片能轻轻托住你，明天再整理也来得及。"),
        PostcardNarrative(id: "xiaoman_hamster_care10_01_002", animalKey: "xiaoman_hamster", careCategory: .nightCare, body: "今天不用把所有事都想明白。先把灯调暗一点，肩膀放松一点。小满觉得，能让自己缓一缓，也是一件很认真的事。"),
        PostcardNarrative(id: "xiaoman_hamster_care10_01_003", animalKey: "xiaoman_hamster", careCategory: .nightCare, body: "有些话说不出来，就暂时不说吧。先吃点热的，换件软一点的衣服。小满希望你读到这里时，心里能少紧一点。"),
        PostcardNarrative(id: "xiaoman_hamster_care10_01_004", animalKey: "xiaoman_hamster", careCategory: .nightCare, body: "是不是用了很多力气？给自己留一小段空白时间。哪怕只是发呆几分钟，也算把自己从忙乱里轻轻捡回来。"),
        PostcardNarrative(id: "xiaoman_hamster_care10_01_005", animalKey: "xiaoman_hamster", careCategory: .nightCare, body: "不太顺也没关系。洗个澡，把今天放到门外一会儿。小满想说，你没有做得很糟，你只是有点累了。"),
        PostcardNarrative(id: "xiaoman_hamster_care10_01_006", animalKey: "xiaoman_hamster", careCategory: .nightCare, body: "肩膀很沉的时候，把它放低一点。呼吸不用很深，能慢一点就好。你已经走了很远，小满看得见。"),
        PostcardNarrative(id: "xiaoman_hamster_care10_01_007", animalKey: "xiaoman_hamster", careCategory: .nightCare, body: "睡前少想一点吧。不是逃开，是让心有地方休息。等明天醒来，再一点点看，也可以。"),
        PostcardNarrative(id: "xiaoman_hamster_care10_01_008", animalKey: "xiaoman_hamster", careCategory: .nightCare, body: "有一点难过也可以。别急着解释，先让身体暖和起来。很多事都会慢慢松开，不用全在今晚完成。"),
